def pre_suggestion_task(source):
    from suggestion_index_source_scope_contract import pre_suggestion_index_source
    source = pre_suggestion_index_source(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_task_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_task(data.decode()).encode() if path.suffix == '.swift' else data

